create table if not exists signals.leads_final(id bigserial primary key, client text, batch text, company text, domain text, data jsonb, created_at timestamptz default now(), unique(client,domain));
insert into signals.leads_final(client,batch,company,domain,data)
select 'pixelserve','clutch_past_buyers_2026-11-24', r->>'Company', r->>'Domain', r from jsonb_array_elements('[{"Company": "Ten Forward Consulting", "Domain": "tenforward.consulting", "Location": "Madison, WI", "Employees (Clay)": 3, "What they do": "custom software dev shop", "Decision maker": "Brian Samson", "Title": "President", "LinkedIn": "https://www.linkedin.com/in/374b936/", "Signal (Clutch review)": "Left a 1-star Clutch review of Social Bloom (Mar 2026): missed deadlines, slow replies, six unproductive meetings.", "Agency used": "Social Bloom", "Period": "Mar 2026", "Status": "churned", "Review rating": 1.0, "LLM intent (Qwen 7B)": 9, "LLM can sell": "yes", "LLM verdict": "approved", "My intent": 9, "Can sell GTM service": "Yes", "Connection note": "Hi Brian, read your Clutch review of Social Bloom. Six meetings that went nowhere is a rough way to spend a quarter. I build outbound for small dev shops and I''d like to connect.", "Follow-up 1": "Thanks for connecting, Brian. Your review stuck with me because most bad outbound fails the same way: a generic list and copy that sounds like every other dev shop. Ten Forward has 14 years of Fortune 500 and startup work. That story never reached the right people.", "Follow-up 2": "Here is what I''d do differently: pick 25 companies that just raised or posted a product role in the Midwest, write to the CTO about their specific build, and only count meetings you''d actually take. I''m Hamza, a GTM engineer. Happy to build that list for free so you can judge it before spending anything.", "Follow-up 3": "Last note from me. Every month without a working outbound channel is a month of projects going to whoever did reach those CTOs first. If you want the free 25-account list, reply ''list''. If not, no hard feelings. cal.com/hamzamunyr/30min"}, {"Company": "Orgwide", "Domain": "orgwide.com", "Location": "Memphis, TN", "Employees (Clay)": 7, "What they do": "custom eLearning studio", "Decision maker": "Bill Rahner", "Title": "VP", "LinkedIn": "https://www.linkedin.com/in/bill-rahner-b8a01bb/", "Signal (Clutch review)": "Left a 1-star Clutch review of CIENCE: poor meeting quality, no-shows, high bounce rates.", "Agency used": "CIENCE", "Period": "Jul 2022", "Status": "churned", "Review rating": 1.0, "LLM intent (Qwen 7B)": 9, "LLM can sell": "yes", "LLM verdict": "approved", "My intent": 9, "Can sell GTM service": "Yes", "Connection note": "Hi Bill, saw Orgwide''s Clutch review of CIENCE (no-shows and bounced emails). That''s a common outcome with volume shops. I build smaller, cleaner outbound for L&D firms. Glad to connect.", "Follow-up 1": "Thanks Bill. With Levi''s, Marriott and St. Jude already on your client list, the proof is there. The problem with CIENCE-style outbound is volume: bad data means bounced email and meetings that don''t show.", "Follow-up 2": "I''m Hamza, a GTM engineer. I build verified lists of L&D and HR leaders at companies that just announced reorgs, new hires in training, or compliance deadlines, then write to them about that event. I can send 25 of those accounts for free so you can see the quality first.", "Follow-up 3": "Closing the loop. Training budgets for 2027 get set in the next few weeks, and the firms that are in the conversation now get the projects. If the free list is useful, reply ''yes''. If not, all good. cal.com/hamzamunyr/30min"}, {"Company": "Canalini Consulting Group", "Domain": "canalini.com", "Location": "Washington, DC", "Employees (Clay)": 12, "What they do": "legal IT consultancy", "Decision maker": "Michael Canalini", "Title": "Founder & CEO", "LinkedIn": "https://www.linkedin.com/in/michael-canalini-2a116358/", "Signal (Clutch review)": "Ran outbound with Martal Group Aug to Dec 2025; wanted earlier metric visibility.", "Agency used": "Martal Group", "Period": "Aug to Dec 2025", "Status": "ended", "Review rating": 5.0, "LLM intent (Qwen 7B)": 9, "LLM can sell": "yes", "LLM verdict": "approved", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi Michael, saw Canalini worked with Martal Group late last year and wanted earlier visibility on metrics. I build outbound for niche IT firms with reporting from day one. Would be glad to connect.", "Follow-up 1": "Thanks Michael. Legal IT is a tight niche: maybe a few thousand firms that matter, each with an IT director who gets pitched daily. Generic outbound burns that list fast.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target law firms showing real triggers (Citrix renewals, Intune migrations, new CIO hires) and give you a live dashboard from week one. I can build the first 25 accounts for free so you can judge the targeting.", "Follow-up 3": "Closing the loop. Firms planning 2027 Azure and security projects are picking partners now. If you want the free 25 firm list, reply ''yes''. cal.com/hamzamunyr/30min"}, {"Company": "4Labs Digital", "Domain": "4labsdigital.com", "Location": "New York, NY", "Employees (Clay)": 17, "What they do": "audience-driven marketing agency", "Decision maker": "Jay Cassano", "Title": "Co-Founder & CEO", "LinkedIn": "https://www.linkedin.com/in/jcassano/", "Signal (Clutch review)": "Ran outbound with Revit Mar to Nov 2025, engagement now over.", "Agency used": "Revit", "Period": "Mar to Nov 2025", "Status": "ended", "Review rating": 4.5, "LLM intent (Qwen 7B)": 1, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi Jay, noticed 4Labs ran outbound with Revit through November 2025. Curious what''s filling the pipeline now. I build outbound for small agencies and would love to connect.", "Follow-up 1": "Thanks Jay. Agencies with a storytelling angle like yours usually lose momentum when an outbound partner leaves, because referrals alone can''t keep 17 people busy.", "Follow-up 2": "I''m Hamza, a GTM engineer. I set up done-for-you outbound that runs on buying signals (new CMOs, rebrands, funding) instead of cold lists, so the first message has a real reason to exist. Want 25 brands with a live trigger this month, free, to see if it fits?", "Follow-up 3": "Last one from me. Q1 budgets are being assigned now, and the agencies who reach new CMOs in their first 90 days usually win them. Reply ''send it'' and I''ll share the 25 accounts. cal.com/hamzamunyr/30min"}, {"Company": "Ranq", "Domain": "ranq.io", "Location": "Dallas, TX", "Employees (Clay)": 14, "What they do": "boutique SEO agency", "Decision maker": "Imad Khwaja", "Title": "Managing Partner", "LinkedIn": "https://www.linkedin.com/in/imad-khwaja-81b3534a/", "Signal (Clutch review)": "Used Funnel Bakers for outbound until June 2024, no provider since on record.", "Agency used": "Funnel Bakers", "Period": "Aug 2023 to Jun 2024", "Status": "ended", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi Imad, saw Ranq used Funnel Bakers for outbound until mid 2024. Small elite teams like yours are exactly who I build outbound for. Would be glad to connect.", "Follow-up 1": "Thanks Imad. ''No junior staff, lean client portfolio'' is a strong pitch, but it only works if the right companies hear it. Since outbound stopped, it''s mostly been referrals, I''d guess.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target companies whose organic traffic dropped after recent Google updates, and open with their own numbers. That gets replies. Want me to pull 25 of those for free?", "Follow-up 3": "Last note. Every month a traffic drop goes unfixed, those companies are shopping for an SEO partner, and someone else will reach them. Reply ''list'' for the free 25. cal.com/hamzamunyr/30min"}, {"Company": "Biohackers World", "Domain": "biohackers.world", "Location": "New York, NY", "Employees (Clay)": 24, "What they do": "wellness conference and expo", "Decision maker": "Mick Safron", "Title": "CEO", "LinkedIn": "https://www.linkedin.com/in/micksafron/", "Signal (Clutch review)": "Ran cold email for sponsors/exhibitors with Leadowski until May 2025; next expo is Miami, Jan 16-17 2027.", "Agency used": "Leadowski", "Period": "Nov 2024 to May 2025", "Status": "ended", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi Mick, saw you ran cold email with Leadowski until May 2025. With Miami on Jan 16-17, I''m guessing sponsor and exhibitor slots are the focus right now. Would be glad to connect.", "Follow-up 1": "Thanks Mick. Event sales has a hard deadline: unsold booths after January are revenue that never comes back.", "Follow-up 2": "I''m Hamza, a GTM engineer. I build outbound to longevity, supplement and health-tech brands that are actively launching or raising, so the sponsorship ask lands at the right moment. Want 25 brands with a live trigger, free, to see if they''re worth a pitch?", "Follow-up 3": "Last one. About 7 weeks to Miami. If the free list helps fill booths, reply ''send''. If not, good luck with the show. cal.com/hamzamunyr/30min"}, {"Company": "Vima Internet Marketing", "Domain": "vimamarketing.com", "Location": "Gilbert, AZ", "Employees (Clay)": 2, "What they do": "law-firm SEO agency", "Decision maker": "John Pace", "Title": "Company Owner", "LinkedIn": "https://www.linkedin.com/in/johnlpace/", "Signal (Clutch review)": "Outbound with Funnel Bakers ended Aug 2025.", "Agency used": "Funnel Bakers", "Period": "Feb to Aug 2025", "Status": "ended", "Review rating": 5.0, "LLM intent (Qwen 7B)": 9, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi John, saw Vima ran outbound with Funnel Bakers in 2025. Law-firm SEO is a great niche for outbound. I build it for small agencies and would like to connect.", "Follow-up 1": "Thanks John. Law firms buy SEO when something changes: a new partner, a new practice area, a competitor outranking them. Those moments are public.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d find firms that just added a practice area or partner and show them who''s outranking them for it. Happy to pull 25 of those firms for free.", "Follow-up 3": "Last one. Firms set 2027 marketing budgets in the next few weeks. Reply ''list'' and I''ll send the 25. cal.com/hamzamunyr/30min"}, {"Company": "Catalyzr", "Domain": "catalyzr.com", "Location": "Stonington, ME", "Employees (Clay)": 7, "What they do": "HR tech SaaS (attrition prediction)", "Decision maker": "Trevor Higgs", "Title": "Co-Founder", "LinkedIn": "https://www.linkedin.com/in/trevorhiggs/", "Signal (Clutch review)": "Short Purple Sales engagement in 2024 lifted leads 2-3x, then stopped.", "Agency used": "Purple Sales", "Period": "Jul to Aug 2024", "Status": "ended", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi Trevor, saw your short Purple Sales campaign lifted leads 2-3x. Curious why it stopped there. I build outbound for early HR tech teams and would like to connect.", "Follow-up 1": "Thanks Trevor. A 2-3x lift that stops is usually a budget or fit issue, not a channel issue. Trucking, call centers and healthcare all have very visible attrition signals.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target companies posting the same frontline role again and again, which is the clearest sign attrition is hurting them, and open with that. Want 25 of those, free?", "Follow-up 3": "Last note. Those repeat postings cost each company money every week they stay open, and your CQ score is the answer. Reply ''send'' for the free list. cal.com/hamzamunyr/30min"}, {"Company": "Agentman", "Domain": "agentman.ai", "Location": "San Francisco, CA", "Employees (Clay)": 4, "What they do": "AI back office for medical practices", "Decision maker": "Prasad Thammineni", "Title": "Founder and CEO", "LinkedIn": "https://www.linkedin.com/in/prasadt/", "Signal (Clutch review)": "SalesRoads outbound since Apr 2026; reaching busy medical practices was hard.", "Agency used": "SalesRoads", "Period": "Apr 2026", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 9, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 8, "Can sell GTM service": "Yes", "Connection note": "Hi Prasad, saw Agentman is running outbound with SalesRoads and that busy medical practices are hard to reach. That''s the exact problem I work on. Would be glad to connect.", "Follow-up 1": "Thanks Prasad. Independent practices rarely answer cold calls, but they do post about prior auth headaches and hire billing staff, both public signals.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target practices hiring prior-auth or billing roles and reach the owner on LinkedIn about that cost. Want 25 for free to run next to SalesRoads?", "Follow-up 3": "Last note. Each of those job posts is a practice paying for the problem Medman solves. Reply ''list'' and I''ll send 25. cal.com/hamzamunyr/30min"}, {"Company": "Etch Advisors", "Domain": "etchadvisors.com", "Location": "Scottsdale, AZ", "Employees (Clay)": 4, "What they do": "fractional CMO for fintech", "Decision maker": "Mary Anne Keegan", "Title": "CEO", "LinkedIn": "https://www.linkedin.com/in/makeegan/", "Signal (Clutch review)": "Long-time buyer of outsourced appointment setting (SSM).", "Agency used": "Strategic Sales & Marketing", "Period": "2014 to now", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 9, "LLM can sell": "yes", "LLM verdict": "approved", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Mary Anne, saw Etch has used outsourced appointment setting for years. Fintech marketing is a sharp niche. I''d be glad to connect.", "Follow-up 1": "Thanks Mary Anne. Fintechs need senior marketing help at clear moments: a raise, a new CEO, a rebrand, or a regulatory change.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target fintech and payments companies hitting those moments and write to the CEO about them. Happy to send 25 for free to compare with your current setter.", "Follow-up 3": "Last one. Fintechs that raised this quarter are hiring marketing help now. Reply ''list'' for the free 25. cal.com/hamzamunyr/30min"}, {"Company": "Data-Command", "Domain": "data-command.com", "Location": "Akron, OH", "Employees (Clay)": 7, "What they do": "SCADA and remote monitoring for municipalities", "Decision maker": "Glenn King", "Title": "Owner and CEO", "LinkedIn": "https://www.linkedin.com/in/glennrking/", "Signal (Clutch review)": "Hired Leadium Oct 2025 to sell a technical product to municipalities.", "Agency used": "Leadium", "Period": "Oct 2025", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Glenn, saw Data-Command brought in Leadium last fall to reach municipalities. Selling SCADA to water districts is a long game. I''d be glad to connect.", "Follow-up 1": "Thanks Glenn. Municipal buyers move when there''s a trigger: an EPA notice, a grant award, a cybersecurity incident nearby. Most agencies don''t watch those.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d build a list of utilities that just received infrastructure grants or failed an audit, and write to the operator about it. Happy to send 25 for free to compare against what you get now.", "Follow-up 3": "Last one. Grant money has spending deadlines, and those utilities are choosing vendors now. Reply ''list'' if the 25 would help. cal.com/hamzamunyr/30min"}, {"Company": "Blaze", "Domain": "blaze.ai", "Location": "San Francisco, CA", "Employees (Clay)": 26, "What they do": "AI marketing agent (SaaS)", "Decision maker": "Liam Devine", "Title": "Head of Growth", "LinkedIn": "https://www.linkedin.com/in/liam-devine-656b6563/", "Signal (Clutch review)": "Martal Group engagement since Apr 2026; ICP calibration took weeks.", "Agency used": "Martal Group", "Period": "Apr 2026", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Liam, saw Blaze is running outbound with Martal and that ICP calibration took a few weeks. I build signal-based outbound for SaaS teams. Would be glad to connect.", "Follow-up 1": "Thanks Liam. With a product that markets for small businesses, the hard part is finding owners at the moment they give up on doing marketing themselves.", "Follow-up 2": "I''m Hamza, a GTM engineer. Signals like ''hiring a social media manager'' or ''just opened a second location'' catch that moment. I can pull 25 of those for free to run next to what Martal sends.", "Follow-up 3": "Closing the loop. If the free list beats your current batch, that''s an easy win for Q1. Reply ''send''. cal.com/hamzamunyr/30min"}, {"Company": "MedTrans Go", "Domain": "medtransgo.com", "Location": "Atlanta, GA", "Employees (Clay)": 26, "What they do": "healthcare appointment logistics platform", "Decision maker": "Dana Weeks", "Title": "Co-Founder & CEO", "LinkedIn": "https://www.linkedin.com/in/danaw1/", "Signal (Clutch review)": "Bought appointment setting from Belkins starting Apr 2024.", "Agency used": "Belkins", "Period": "Apr 2024", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Dana, saw MedTrans Go bought appointment setting from Belkins. Healthcare logistics is a hard sell cold. I build outbound for health-tech teams and would like to connect.", "Follow-up 1": "Thanks Dana. Cancellation pain shows up publicly: patient reviews mentioning rides and interpreters, or facilities hiring care coordinators.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target facilities and law offices showing exactly that and write to them about their own no-show problem. Want 25 of those for free?", "Follow-up 3": "Last note. Every no-show costs those facilities money today, which is why timing matters. Reply ''list'' for the free 25. cal.com/hamzamunyr/30min"}, {"Company": "BEST Lending Co", "Domain": "bestlendingco.com", "Location": "San Diego, CA", "Employees (Clay)": 5, "What they do": "private lending for RE investors", "Decision maker": "Ben Stoodley", "Title": "CEO", "LinkedIn": "https://www.linkedin.com/in/benstoodley/", "Signal (Clutch review)": "Running cold email with Social Bloom since Jun 2026.", "Agency used": "Social Bloom", "Period": "Jun 2026", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Ben, saw BEST Lending is running cold email with Social Bloom. Private lending to investors is a strong outbound fit. Would be glad to connect.", "Follow-up 1": "Thanks Ben. Investors look for new lenders when they''re buying: new LLC filings, recent purchases, or a property listed for rehab.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d add LinkedIn outreach to active investors next to your email, triggered by those deals. Happy to build 25 for free so you can compare.", "Follow-up 3": "Closing the loop. Spring deal flow gets financed in Q1. Reply ''yes'' for the free list. cal.com/hamzamunyr/30min"}, {"Company": "Cloud Propeller", "Domain": "cloudpropeller.com", "Location": "Dublin, OH", "Employees (Clay)": 3, "What they do": "managed cloud provider", "Decision maker": "Petar Smilajkov", "Title": "CEO & Chief Architect", "LinkedIn": "https://www.linkedin.com/in/peconi/", "Signal (Clutch review)": "Outsourced outbound to CallingAgency since Apr 2026.", "Agency used": "CallingAgency", "Period": "Apr 2026", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Petar, saw Cloud Propeller started outbound with CallingAgency this year. Engineer-led cloud providers are a great fit for signal-based outreach. Glad to connect.", "Follow-up 1": "Thanks Petar. Companies switch hosting when something hurts: an outage, a renewal from VMware/Broadcom pricing, or an IT lead leaving.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d find Ohio-area firms hit by those triggers and write to them about it. Want 25 for free to compare with your current calls?", "Follow-up 3": "Last one. Renewal season is when those switches happen. Reply ''list'' if the 25 would help. cal.com/hamzamunyr/30min"}, {"Company": "Meet Sona", "Domain": "meetsona.ai", "Location": "San Luis Obispo, CA", "Employees (Clay)": 1, "What they do": "AI thought-leadership writing tool", "Decision maker": "Ken Marshall", "Title": "Co-Founder", "LinkedIn": "https://www.linkedin.com/in/kenmagma/", "Signal (Clutch review)": "Hired Social Bloom Aug 2026; onboarding steps were unclear.", "Agency used": "Social Bloom", "Period": "Aug 2026", "Status": "active", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 7, "Can sell GTM service": "Yes", "Connection note": "Hi Ken, saw Meet Sona brought in Social Bloom in August. Selling a LinkedIn writing tool through outbound is fun to get right. Would be glad to connect.", "Follow-up 1": "Thanks Ken. Your best buyers are executives who post once and then go quiet. That gap is visible on their profiles.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d find execs whose posting stopped after a strong start and open with their own last post. I can pull 25 for free.", "Follow-up 3": "Closing the loop. January is when execs promise to post more. Reply ''yes'' for the free 25. cal.com/hamzamunyr/30min"}, {"Company": "Workee", "Domain": "workee.ai", "Location": "Miami, FL", "Employees (Clay)": 18, "What they do": "AI booking software for clinics", "Decision maker": "Ihor Bauman", "Title": "Founder & CEO", "LinkedIn": "https://www.linkedin.com/in/ihor-bauman/", "Signal (Clutch review)": "Past outsourced campaign buyer; wanted more detailed reporting.", "Agency used": "Leadowski", "Period": "Aug 2022", "Status": "past", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 6, "Can sell GTM service": "Maybe", "Connection note": "Hi Ihor, saw Workee has bought outbound before. Med spas and wellness clinics are a great outbound market when the timing is right. Would be glad to connect.", "Follow-up 1": "Thanks Ihor. Clinics switch booking tools when something breaks: bad reviews about scheduling, a second location, or a Vagaro price change.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d find clinics opening new locations or getting no-show complaints in reviews and write to the owner about that. I can build 25 for free so you can judge it.", "Follow-up 3": "Closing the loop. January is when clinics fix their booking stack. Reply ''yes'' for the free 25. cal.com/hamzamunyr/30min"}, {"Company": "SelectSoftware Reviews", "Domain": "selectsoftwarereviews.com", "Location": "Cambridge, MA", "Employees (Clay)": 22, "What they do": "HR software research site", "Decision maker": "Jennifer Sales", "Title": "Chief Revenue Officer", "LinkedIn": "https://www.linkedin.com/in/jennifer-sales/", "Signal (Clutch review)": "Past Social Bloom buyer; had early trouble with target market research. New CRO since Jan 2025.", "Agency used": "Social Bloom", "Period": "Jul 2021", "Status": "past", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "no", "LLM verdict": "rejected", "My intent": 6, "Can sell GTM service": "Maybe", "Connection note": "Hi Jennifer, saw SSR has worked with outbound partners before and you joined as CRO last year. I build signal-based outbound for media and research sites. Glad to connect.", "Follow-up 1": "Thanks Jennifer. Vendor revenue for a review site depends on catching HR tech companies right after they raise or launch, when budget for visibility is fresh.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target HR tech vendors that raised or launched in the last 60 days. I can pull 25 for free so your team can test it.", "Follow-up 3": "Closing the loop. Those budgets get spent fast after a raise. Reply ''send'' for the free list. cal.com/hamzamunyr/30min"}, {"Company": "Kitchen Logistics (Neuline)", "Domain": "neuline.com", "Location": "Lancaster, TX", "Employees (Clay)": 8, "What they do": "nobilia kitchen cabinet distributor", "Decision maker": "Dwayne Lusk", "Title": "President", "LinkedIn": "https://www.linkedin.com/in/dwayne-lusk-3b342613/", "Signal (Clutch review)": "Bought a Belkins email campaign in 2023.", "Agency used": "Belkins", "Period": "Aug 2023", "Status": "past", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 6, "Can sell GTM service": "Maybe", "Connection note": "Hi Dwayne, saw Neuline ran an email campaign with Belkins. Selling nobilia kitchens to Texas builders is a great outbound fit. Would be glad to connect.", "Follow-up 1": "Thanks Dwayne. Builders and designers choose cabinet partners when they win new projects, and permits and project announcements are public.", "Follow-up 2": "I''m Hamza, a GTM engineer. I''d target Texas builders with new multifamily or luxury permits and reach them on LinkedIn. Want 25 for free?", "Follow-up 3": "Closing the loop. Spring projects are being specified now. Reply ''yes'' for the free list. cal.com/hamzamunyr/30min"}, {"Company": "SaylzeVP", "Domain": "saylzevp.com", "Location": "Evanston, IL", "Employees (Clay)": 1, "What they do": "fractional VP of Sales", "Decision maker": "Doug Miller", "Title": "President, Fractional CRO", "LinkedIn": "https://www.linkedin.com/in/dmiller722/", "Signal (Clutch review)": "Used Salaria for outsourced business development.", "Agency used": "Salaria Sales Solutions", "Period": "Jan 2021", "Status": "past", "Review rating": 5.0, "LLM intent (Qwen 7B)": 1, "LLM can sell": "maybe", "LLM verdict": "rejected", "My intent": 6, "Can sell GTM service": "Maybe", "Connection note": "Hi Doug, saw you''ve used Salaria for outsourced business development. As a fractional CRO, your clients probably need outbound too. Would be glad to connect.", "Follow-up 1": "Thanks Doug. Fractional sales leaders often find the gap is not process but pipeline: the team is coached, but there aren''t enough conversations.", "Follow-up 2": "I''m Hamza, a GTM engineer. I build done-for-you outbound you could pair with your engagements, and for your own pipeline I''d target companies that just lost a VP Sales. Want 25 of those, free?", "Follow-up 3": "Last note. Those companies are deciding between hiring and going fractional right now. Reply ''list'' for the free 25. cal.com/hamzamunyr/30min"}]'::jsonb) r
on conflict (client,domain) do update set data=excluded.data returning id;